import{_ as o,o as t,c as d,a2 as c}from"./chunks/framework.a6FUKr6c.js";const u=JSON.parse('{"title":"Upgrading","description":"","frontmatter":{},"headers":[],"relativePath":"guide/upgrading.md","filePath":"guide/upgrading.md","lastUpdated":1795180689000}'),a={name:"guide/upgrading.md"};function n(r,e,i,s,h,l){return t(),d("div",null,[...e[0]||(e[0]=[c('<h1 id="upgrading" tabindex="-1">Upgrading <a class="header-anchor" href="#upgrading" aria-label="Permalink to &quot;Upgrading&quot;">​</a></h1><p>chamvi is pre-1.0: a minor release may break the API. Each section lists what changed and the exact replacement.</p><h2 id="upgrading-to-0-10" tabindex="-1">Upgrading to 0.10 <a class="header-anchor" href="#upgrading-to-0-10" aria-label="Permalink to &quot;Upgrading to 0.10&quot;">​</a></h2><p>A connection row is identified by its id, its generation, never by a timestamp: a save made from a form that another save, a WhatsApp reset or a delete and create replaced answers 409 <code>connection_changed</code>, and the dashboard keeps the typed values and offers <strong>Reload values</strong>. No migration: the id is the row&#39;s existing primary key.</p><p>One store migration, <code>LockTokens1795093873329</code>, runs like any other (<code>CHAMVI_MIGRATE</code>, <code>chamvi migrate</code>): it adds the table <code>chamvi_lock_tokens</code> and the column <code>chamvi_locks.token</code> (bigint, <code>NOT NULL</code>), filled for the stored locks in the same transaction. Lock tokens start at the wall clock in microseconds, so a recreated or switched lock store issues tokens above those an earlier store handed out as long as its host&#39;s clock (in microseconds) is past the highest of them. A host whose clock is behind (clock skew, or the same millisecond as the last issued token), like a wall clock set back, issues lower tokens: a fenced writer (a knowledge collection) then refuses its writes until the clock catches up. Once migrated, <code>chamvi_locks.token</code> is <code>NOT NULL</code>, so a replica of an older version that is still running cannot take a new lock (every lock insert fails): stop old replicas before or while migrating (the <code>agent-app</code> chart&#39;s <code>Recreate</code> strategy does this; suspend run-job CronJobs too).</p><p>Agents can run in another chamvi app (<a href="/guide/remote-agents">Remote agents</a>): <code>defineRemoteAgent()</code>, the new package <code>@chamvi/peer</code> with <code>peerModule()</code>, and <code>AppToken.PEERS</code>. Nothing changes for an app that configures no peer. <code>@chamvi/http</code> adds the route <code>POST /runs/:id/wake</code> (peers only; anyone else gets 404) and the error code <code>peer_start_busy</code> (503 with <code>Retry-After</code>, a peer&#39;s start only); a run can store the code <code>remote_failed</code>, and a waiting run the wait kind <code>remote</code>. A client that switches over <code>run.waiting.kind</code> must handle <code>remote</code>. <code>GET /agents</code> lists a remote agent with <code>kind: &#39;remote&#39;</code> and <code>remote: { peer, agent }</code>.</p><h3 id="breaking-changes" tabindex="-1">Breaking changes <a class="header-anchor" href="#breaking-changes" aria-label="Permalink to &quot;Breaking changes&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Change</th><th>Before</th><th>Replacement</th></tr></thead><tbody><tr><td><code>Connection</code> (<code>@chamvi/store</code>)</td><td>No id</td><td><code>id: string</code>, the row&#39;s uuid v7, set at insert and never changed. <code>ConnectionService.create()</code> and <code>replace()</code> take <code>ConnectionInput</code> (<code>Omit&lt;Connection, &#39;id&#39;&gt;</code>); the service assigns the id</td></tr><tr><td><code>IConnectionService.writeConfig()</code> (<code>@chamvi/core</code>)</td><td><code>writeConfig(name, write, expectedWrappedKey, expectedRevision?)</code></td><td><code>writeConfig(name, write, { wrappedKey, revision?, generation? })</code> (<code>ConnectionWriteExpectation</code>); a stored id other than <code>generation</code> is <code>ConnectionChangedError</code> too</td></tr><tr><td><code>ConnectionService.replace()</code> (<code>@chamvi/core</code>)</td><td>Kept the config revision and took <code>createdAt</code> from the replacement</td><td>Bumps the config revision, so a save that read before a reset is refused; keeps the row&#39;s <code>createdAt</code></td></tr><tr><td><code>ConnectionConfig</code>, <code>ConnectionConfigView</code>, <code>IConnectionConfigStore.read()</code> (<code>@chamvi/core</code>)</td><td><code>revision</code> only</td><td>Also <code>generation</code> (the row id); <code>ConnectionConfigUpdateOptions</code> takes <code>generation</code> next to <code>revision</code></td></tr><tr><td><code>DeclaredConnection.loadedCreatedAt</code> (<code>@chamvi/core</code>), <code>StoredConnection.createdAt</code> (<code>@chamvi/app</code>)</td><td>The loaded row&#39;s creation time</td><td><code>loadedGeneration</code> and <code>id</code>: set <code>loadedGeneration: row.id</code> from <code>readStoredConnections()</code> in a third-party connection type</td></tr><tr><td>Stored connection settings (<code>@chamvi/core</code>)</td><td>Only the HTTP layer checked values; a direct <code>IConnectionConfigStore</code> or <code>writeConfig</code> caller could store <code>undefined</code>, a <code>Date</code>, a nested object or text with NUL, and memory and Postgres answered differently</td><td><code>ConnectionService</code> refuses with <code>ValidationError</code> anything but well-formed text without NUL, finite numbers, booleans and lists of such text (keys well-formed without NUL), for every driver (<code>assertConnectionSettings()</code>, <code>isStorableConnectionText()</code>)</td></tr><tr><td><code>PUT /connections/:name/config</code> (<code>@chamvi/http</code>)</td><td>The body carried <code>settings</code> and <code>secrets</code> only, and the later of two saves won</td><td>The body needs <code>revision</code> (400 without) and the <code>generation</code> of the <code>GET /connections/:name/config</code> it was made from (both in that view; no <code>generation</code> and <code>revision: 0</code> before the first save). Another revision or generation stored now answers 409 <code>connection_changed</code>. <code>ConnectionSaveBody</code> and <code>ConnectionSettingsView</code> (<code>@chamvi/http</code>, <code>@chamvi/http-kit</code>) carry both</td></tr><tr><td><code>useConnectionForm()</code> (<code>@chamvi/ui-kit</code>)</td><td>A save overwrote whatever another tab saved meanwhile</td><td>It sends the view&#39;s version; on <code>connection_changed</code> it sets <code>stale</code> (Save disabled, typed values kept) until <code>reload()</code> loads the stored config</td></tr><tr><td><code>IKnowledgeRepository</code>, <code>MemoryKnowledgeRepository</code> (<code>@chamvi/knowledge</code>)</td><td>One interface holding every storage operation and rule, implemented by each backend</td><td>Removed. Storage is three entity ports on <code>@chamvi/store</code>&#39;s <code>IEntityRepository</code> (<code>IKnowledgeCollectionRepository</code> with its children <code>documents</code> and <code>chunks</code>), and <code>KnowledgeService</code> holds the rules: call the service (<code>knowledge.service</code>, or <code>new KnowledgeService({ repository, clock })</code>) where you called the repository. A custom backend implements the three ports, keeps each collection row&#39;s <code>id</code> and <code>fence</code>, and passes <code>describeKnowledgeRepositoryContract()</code></td></tr><tr><td><code>createMemoryKnowledgeRepository()</code> (<code>@chamvi/knowledge</code>)</td><td>Returned a <code>MemoryKnowledgeRepository</code></td><td>Returns the root port <code>IKnowledgeCollectionRepository</code>; <code>createKnowledge({ repository })</code> and <code>knowledgeModule({ repository })</code> take it as before</td></tr><tr><td><code>IKnowledge.repository</code> (<code>@chamvi/knowledge</code>)</td><td>The <code>IKnowledgeRepository</code></td><td>The root port; reads and writes go through the new <code>IKnowledge.service</code></td></tr><tr><td><code>describeKnowledgeRepositoryContract()</code> (<code>@chamvi/test-kit</code>)</td><td><code>(name, create)</code>, <code>create</code> returning a repository</td><td><code>({ name, create })</code>, <code>create</code> returning a <code>KnowledgeService</code> over fresh repositories</td></tr><tr><td><code>ILockService.acquire()</code>, <code>LockService.acquire()</code> (<code>@chamvi/core</code>)</td><td>Resolved <code>true</code> when granted, <code>false</code> when refused</td><td>Resolves the lease&#39;s fencing token (a <code>number</code>) when granted, <code>undefined</code> when refused: test <code>!== undefined</code> where you tested the boolean. The token is higher than every token the lock store issued before, for any key; <code>renew</code> keeps it. <code>createRepositoryScheduleLock()</code> (<code>@chamvi/channel-cron</code>) still resolves a boolean for hubwire</td></tr><tr><td><code>Lock</code>, <code>ILockRepository</code> (<code>@chamvi/store</code>)</td><td><code>Lock</code> was <code>id</code>, <code>key</code>, <code>owner</code>, <code>expiresAt</code></td><td><code>Lock.token: number</code> and <code>ILockRepository.nextToken()</code>: a custom lock repository stores <code>token</code> as given and issues <code>max(last + 1, Date.now() * 1000)</code>, strictly increasing across all keys and concurrent callers, and passes <code>describeLockRepositoryContract()</code></td></tr><tr><td><code>createKnowledge({ locks })</code> (<code>@chamvi/knowledge</code>)</td><td><code>Pick&lt;ILockService, &#39;acquire&#39; | &#39;release&#39;&gt;</code></td><td>Also <code>renew</code>: a pass renews its lease in place and keeps the lock&#39;s fencing token, which it claims as the collection&#39;s fence. Pass <code>engine.lockService</code></td></tr></tbody></table><h2 id="upgrading-to-0-9" tabindex="-1">Upgrading to 0.9 <a class="header-anchor" href="#upgrading-to-0-9" aria-label="Permalink to &quot;Upgrading to 0.9&quot;">​</a></h2><p>Connections can be configured in the dashboard, on a page per provider (<a href="/guide/ui#connection-pages">Connection pages</a>). An env-only deployment keeps working once <code>CHAMVI_TOKENS</code> uses the new permission format (<code>&quot;permissions&quot;: &quot;*&quot;</code> or a list of bindings, see Permissions below; the old string list, also <code>[&quot;*&quot;]</code>, refuses to start), and <code>CHAMVI_ENCRYPTION_KEYS</code> is needed once the dashboard saves a connection, also one with plain settings only, since every stored connection has its own data key. One migration, <code>ConnectionsRevisionsItemBytes1794230765000</code>, upgrades the 0.8 schema and runs like any other (<code>CHAMVI_MIGRATE</code>, <code>chamvi migrate</code>). It adds the connection settings and secrets tables; the nullable column <code>chamvi_runs.agent_revision</code>, the agent revision a permission-checked run is bound to (existing runs keep it empty and run as before); and the column <code>chamvi_conversation_items.bytes</code> (integer, <code>NOT NULL</code>, no default), the UTF-8 byte length of an item&#39;s text, and fills it for every stored item in the same migration (one <code>UPDATE</code> computing <code>octet_length(text)</code>, then <code>SET NOT NULL</code>). The migration runs in one transaction that holds an exclusive lock on the conversation items, runs and connections tables until it commits: conversation turns, run reads and writes, connection reads and every read of the items table (the recall, the conversation API) wait for it. The migration sets no <code>lock_timeout</code>: each <code>ALTER TABLE</code> first waits for every transaction that touched its table (an old replica, an open <code>psql</code> session), and every later query of those tables queues behind it. It takes about 12 µs a stored item (measured: 500,000 items of 1 KB in 6 s; TOASTed text is not read), so run it at a start or with <code>chamvi migrate</code> before the app serves. Stop every replica of the previous version before migrating: once the column is <code>NOT NULL</code>, an old process fails every item insert (the <code>agent-app</code> chart&#39;s <code>Recreate</code> strategy does this; suspend run-job CronJobs too). <code>POST /agents/:name/runs</code> and webhooks answer 409 <code>agent_replaced</code> when the agent is being replaced at the dispatch; nothing is written, and the caller can retry. Every app serves its OpenAPI document at <code>&lt;basePath&gt;/openapi.json</code> and a Swagger UI at <code>&lt;basePath&gt;/docs</code>, unauthenticated, by default (<a href="/reference/http#openapi-document">OpenAPI document</a>; <code>httpModule({ openapi: false })</code> turns both off). <code>@chamvi/http</code> now installs <code>swagger-ui-dist</code>, whose dependency <code>@scarf/scarf</code> runs a postinstall analytics script unless <code>SCARF_ANALYTICS=false</code> is set where <code>npm install</code> runs (an image build, CI).</p><p>Every app that installs <code>@chamvi/app</code> 0.9 next to <code>typeorm</code> gets an npm <code>ERESOLVE</code>, also without <code>authupModule()</code>: npm resolves <code>@authup/server-adapter-kit</code> (an optional peer of <code>@chamvi/app</code>), which peers <code>ioredis ^6</code>, while typeorm has an optional peer <code>ioredis ^5</code>. chamvi never uses ioredis through typeorm, so pin it in the app&#39;s <code>package.json</code>:</p><div class="language-json"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki chamvi vp-code" tabindex="0"><code><span class="line"><span style="color:#DCE9F2;">{</span></span>\n<span class="line"><span style="color:#DCE9F2;">    &quot;</span><span style="color:#E7C58C;">overrides</span><span style="color:#DCE9F2;">&quot;</span><span style="color:#DCE9F2;">: {</span></span>\n<span class="line"><span style="color:#DCE9F2;">        &quot;</span><span style="color:#E7C58C;">ioredis</span><span style="color:#DCE9F2;">&quot;</span><span style="color:#DCE9F2;">: </span><span style="color:#E7C58C;">&quot;^6.0.0&quot;</span></span>\n<span class="line"><span style="color:#DCE9F2;">    }</span></span>\n<span class="line"><span style="color:#DCE9F2;">}</span></span></code></pre></div><h3 id="breaking-changes-1" tabindex="-1">Breaking changes <a class="header-anchor" href="#breaking-changes-1" aria-label="Permalink to &quot;Breaking changes&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Change</th><th>Before</th><th>Replacement</th></tr></thead><tbody><tr><td>WhatsApp pairing</td><td><code>@chamvi/ui</code> showed the QR on its Connections page</td><td>Add <code>chatWhatsappUiModule()</code> (<code>@chamvi/chat-whatsapp-ui/module</code>) to keep pairing; the QR is at <code>&lt;uiBase&gt;/ext/chat-whatsapp</code>. The generic Connections page keeps the status and Reset session</td></tr><tr><td><code>githubModule()</code> with a missing required variable</td><td>The factory threw</td><td>The factory throws for a malformed value only. A partial env fails the start in <code>setup</code> naming the variable; nothing set starts idle (tools report not configured, webhooks answer 503)</td></tr><tr><td><code>GITHUB_MODULE_NAME</code> (<code>@chamvi/github/module</code>)</td><td>The module&#39;s id</td><td>The prefix only: the id is <code>chamvi:github:&lt;name&gt;</code>, by default <code>chamvi:github:github</code>. Change a <code>dependencies</code> entry that named the old id</td></tr><tr><td>Permissions</td><td>Dynamic strings (<code>agent:&lt;name&gt;:run</code>, <code>run:read</code>, <code>connection:&lt;name&gt;:write</code>, <code>tool:&lt;agent&gt;:&lt;tool&gt;</code>, <code>*</code>)</td><td>Static names (<code>chamvi_agent_run</code>, ...) granted as authup permission bindings, a policy narrowing a grant to an agent or a connection. <code>CHAMVI_TOKENS</code> takes <code>&quot;*&quot;</code> or a list of bindings. See <a href="/guide/permissions#upgrading">Permissions and authup</a></td></tr><tr><td><code>authup()</code> options (<code>@chamvi/http</code>)</td><td><code>{ verifier }</code></td><td><code>{ verifier, catalog, realm }</code>; <code>authupModule()</code>&#39;s client also needs <code>permission_read</code> (realm scope <code>ownOrNull</code> or wider)</td></tr><tr><td><code>hasPermission</code>, <code>matchesPermission</code>, <code>toolPermission</code> (<code>@chamvi/core</code>), <code>agentPermission</code> (<code>@chamvi/http</code>, <code>@chamvi/app</code>)</td><td>String matching</td><td><code>can()</code> and <code>canSome()</code> of <code>@chamvi/access</code> (re-exported by <code>@chamvi/app</code>)</td></tr><tr><td><code>/knowledge</code> routes and <code>KNOWLEDGE_READ_PERMISSION</code>, <code>KNOWLEDGE_WRITE_PERMISSION</code> (<code>@chamvi/knowledge</code>)</td><td><code>knowledge:read</code>, <code>knowledge:write</code></td><td><code>chamvi_knowledge_read</code>, <code>chamvi_knowledge_write</code> (covered by <code>&quot;*&quot;</code>), checked with <code>{ &quot;name&quot;: &quot;&lt;collection&gt;&quot; }</code> when the path names one collection; the two constants hold the new names</td></tr><tr><td><code>Permission</code> and <code>connectionPermission()</code> (<code>@chamvi/http</code>)</td><td><code>Permission</code> held <code>ALL</code> (<code>*</code>), <code>RUN_READ</code>, <code>RUN_CANCEL</code>, <code>STATE_READ</code> and <code>STATE_WRITE</code> as strings (<code>run:read</code>, ...); <code>connectionPermission(name, action)</code> built <code>connection:&lt;name&gt;:&lt;action&gt;</code></td><td>Both removed from <code>@chamvi/http</code>. <code>Permission</code> of <code>@chamvi/access</code> (re-exported by <code>@chamvi/app</code>) holds the static names (<code>Permission.RUN_READ</code> is <code>chamvi_run_read</code>, <code>Permission.CONNECTION_WRITE</code> is <code>chamvi_connection_write</code>, ...); check a connection with <code>await can(principal, Permission.CONNECTION_WRITE, { attributes: { name } })</code></td></tr><tr><td><code>GET /me</code> and the dashboard&#39;s permission gates (<code>@chamvi/http</code>, <code>@chamvi/ui-kit</code>)</td><td><code>/me</code> answered <code>bindings</code> and <code>authorization</code>, which a client evaluated with <code>@chamvi/access</code>; ui-kit exported <code>canAddAccount</code>, <code>canReadConnection</code>, <code>canWriteConnection</code>, <code>useResolved</code>, <code>ResolvedOptions</code> and <code>ConnectionRef</code>, <code>AccountsColumn</code> took a <code>principal</code> prop, and <code>visibleUiPages</code> was async</td><td><code>/me</code> answers <code>{ id, kind, name?, identity? }</code> only. Ask <code>POST /authorization/check</code> with <code>{ names? }</code> for <code>{ permissions }</code>, the names the caller may attempt (an upper bound, the route decides per resource). In ui-kit read <code>session.permissions</code> and <code>session.allowed(name)</code>; <code>visibleUiPages(pages, connections, allowed)</code> is synchronous; pass <code>AccountsColumn</code> <code>can-create</code> (<code>session.allowed(&#39;chamvi_connection_create&#39;)</code>) in place of <code>principal</code></td></tr><tr><td>The dashboard API client (<code>@chamvi/ui-kit</code>)</td><td>ui-kit exported <code>createApiClient</code>, <code>IApiClient</code>, <code>ApiError</code>, <code>toApiError</code>, <code>asApiError</code>, <code>retryDelayOf</code>, <code>path</code>, <code>pageQuery</code>, <code>withQuery</code>, <code>runListQuery</code>, <code>RunListFilter</code>, <code>PageQuery</code>, the wire types (<code>RunWire</code>, <code>ConnectionWire</code>, <code>UiPageWire</code>, ...), the SSE helpers (<code>parseEventStream</code>, <code>sleep</code>, <code>RECONNECT_DELAYS_MS</code>, <code>FATAL_STREAM_STATUSES</code>), <code>createConnectionsApi</code>, <code>createConnectionConfigApi</code>, <code>openConnectionStream</code>, <code>IConnectionsApi</code> and <code>IConnectionConfigApi</code>; <code>AppContext.client</code> was an <code>IApiClient</code> with flat methods (<code>listRuns</code>, <code>getRun</code>, <code>me(token)</code>, <code>send()</code>)</td><td>Import them from the new <code>@chamvi/http-kit</code>. <code>AppContext.client</code> is its <code>IClient</code>, one API per domain: <code>client.run.getMany(query)</code>, <code>client.run.getOne(id)</code>, <code>client.account.getMe({ token })</code>, <code>client.connection.getMany()</code>, ...; <code>useConnections()</code>, <code>useConnection()</code> and <code>ConnectionPanel</code> take <code>client.connection</code>, <code>useConnectionForm()</code> the client. List queries are <a href="https://github.com/tada5hi/rapiq" target="_blank" rel="noreferrer">rapiq</a> input (<code>{ filters, pagination, sorts }</code>); the dashboard&#39;s runs URLs carry rapiq parameters (<code>filter[agent]</code>, <code>page[offset]</code>), so an old <code>?agent=&amp;status=&amp;page=</code> link opens unfiltered</td></tr><tr><td><code>IClock.now()</code> (<code>@chamvi/core</code>)</td><td>Returned a <code>Date</code></td><td>Returns epoch milliseconds (<code>number</code>); wrap it in <code>new Date(clock.now())</code> where a <code>Date</code> is needed. A custom <code>IClock</code> returns <code>Date.now()</code> or its own milliseconds</td></tr><tr><td><code>IClock.setTimeout()</code> (<code>@chamvi/core</code>)</td><td><code>setTimeout(fn, ms, { keepAlive? })</code> returning <code>{ clear }</code>; <code>systemClock</code> timers never held the process unless <code>keepAlive</code> was set</td><td><code>setTimeout(fn, ms)</code> returning <code>ClockTimer</code> (<code>{ clear(), unref?() }</code>); <code>ClockTimerOptions</code> is removed. A <code>systemClock</code> timer holds the process until <code>unref()</code> is called: call <code>timer.unref?.()</code> after arming a timer that must not keep the process alive</td></tr><tr><td><code>ControllableClock</code> (<code>@chamvi/test-kit</code>)</td><td><code>now()</code> returned a <code>Date</code>; the constructor took a <code>Date</code></td><td><code>now()</code> returns epoch milliseconds; the constructor takes a <code>Date</code> or milliseconds (default 0); its timers have no <code>unref()</code></td></tr><tr><td><code>toolPolicy</code></td><td><code>(toolName, { run }) =&gt; boolean</code></td><td><code>(toolName, { run, now }) =&gt; boolean | Promise&lt;boolean&gt;</code> (a synchronous policy keeps working)</td></tr><tr><td>Skill discovery in a <code>prepareSkills()</code>/<code>gitSkills()</code> source (<code>@chamvi/skills</code>)</td><td>The whole repository tree was searched, so a vendored copy of a selected skill made it ambiguous</td><td>The standard locations are searched (root, <code>skills/</code>, agent skill folders, plugin manifests), the whole tree only when those hold no skill. Move a selected skill that lives elsewhere into <code>skills/</code>, or the name fails as missing</td></tr><tr><td>Submodules in a <code>prepareSkills()</code>/<code>gitSkills()</code> source (<code>@chamvi/skills</code>)</td><td>Submodule gitlinks were not checked</td><td>The SDK initialises them; a submodule at, inside or around a selected skill folder refuses the source. Move the submodule or vendor its files. Tracked symlinks anywhere in the source still refuse it</td></tr><tr><td>Private <code>prepareSkills()</code>/<code>gitSkills()</code> sources (<code>@chamvi/skills</code>)</td><td>One clone, which could fall back to the host&#39;s <code>gh</code> login or SSH keys</td><td>A second, file-less fetch of the pinned commit runs with plain Git and no fallback. Configure Git credentials for the source before upgrading; a source reachable only through <code>gh</code> fails with the retryable <code>skill_preparation_failed</code>. See the <a href="/reference/skills">skills reference</a></td></tr><tr><td>Body order on routes with a body (<code>@chamvi/http</code>)</td><td>An authenticated caller without the permission, or one addressing a missing resource, got 403 or 404 before the body was read</td><td>The body is read after authentication and before the permission and existence checks: such a caller gets 400, 413 or 415 for a malformed or oversized body. Anonymous callers still get 401 before any read</td></tr><tr><td>Reserved route segments (<code>@chamvi/http</code>)</td><td>An extra route (<code>routes</code>) could use the first segment <code>docs</code> or <code>openapi.json</code></td><td>Both are built-in routes: an extra route at <code>/docs</code>, <code>/openapi.json</code> or below them (in any letter case), for example the dashboard at <code>uiRoutes({ basePath: &#39;/docs&#39; })</code>, refuses to boot with <code>InvalidAgentDefinitionError</code> (<code>Route path &quot;/docs&quot; collides with a built-in route.</code>), also with <code>openapi: false</code>. Move the route</td></tr><tr><td>Reserved route segment <code>components</code> (<code>@chamvi/http</code>)</td><td>An extra route or a contributed controller could use the first segment <code>components</code></td><td><code>GET /components</code> is a built-in route: an extra route or controller at <code>/components</code> or below refuses to boot with <code>InvalidAgentDefinitionError</code>. Move the route</td></tr><tr><td><code>chamvi_component_read</code> (<code>@chamvi/access</code>)</td><td>Thirteen <code>chamvi_*</code> names</td><td>A new name, covered by <code>&quot;*&quot;</code>: grant it to a principal with a list of bindings that should see <code>GET /components</code> and the dashboard&#39;s Components page (hidden without it)</td></tr><tr><td>Background jobs (<code>@chamvi/app</code>, <code>@chamvi/knowledge</code>)</td><td>The store purge and the agents dir watcher ran as the lifecycle hooks <code>chamvi:purge</code> and <code>chamvi:agents-watcher</code>; <code>knowledgeModule()</code> began indexing in a <code>started</code> hook</td><td>They are <a href="/guide/app#background-components">components</a> (<code>store-purge</code>, <code>agents-watcher</code>, <code>agents-packages</code>, <code>knowledge-managed</code>) of the new built-in <code>chamvi:components</code> module: they start after <code>engine.start()</code> and before the <code>started</code> hooks, and stop in the <code>stopping</code> phase, before the drain. A module that replaced or listed those hooks contributes to <code>AppToken.COMPONENTS</code> instead; a module that replaces <code>chamvi:components</code> must run them</td></tr><tr><td><code>@routup/decorators</code> (<code>@chamvi/http</code>, <code>@chamvi/app</code>)</td><td>A dependency of <code>@chamvi/http</code></td><td>A peer dependency (<code>^5.3.0</code>), for the <a href="/guide/controllers">controllers</a> an app contributes. npm 7 and later and pnpm 8 and later install it: nothing to do. An app installed without automatic peers (npm with <code>--legacy-peer-deps</code>, Yarn Berry, pnpm before 8) lists <code>@routup/decorators</code> in its <code>package.json</code>; otherwise it fails at startup with a module-not-found error</td></tr><tr><td>Errors of <code>GET /connections/:name</code>, <code>GET</code>/<code>PUT /connections/:name/config</code> (<code>@chamvi/http</code>)</td><td>A 403, and on the config routes every error, had no <code>cache-control</code></td><td>Every response the route itself produces (after authentication and the body read), a 403 or 404 included, carries <code>cache-control: private, no-store</code></td></tr><tr><td>Metric <code>path</code> labels (<code>@chamvi/http</code>)</td><td>Every channel shared <code>/channels/:name/*</code>; a request with a method no route of its path serves (<code>OPTIONS</code> included) was labelled by the path&#39;s route</td><td>One label per mounted channel, <code>/channels/&lt;name&gt;/*</code> (<code>/channels/github/*</code>); such a request is labelled <code>/_unmatched</code>. Update the dashboards and alerts that select <code>path=&quot;/channels/:name/*&quot;</code></td></tr><tr><td>A TypeScript entry (<code>@chamvi/cli</code>): <code>chamvi dev</code>, and <code>start</code>, <code>run-job</code> or <code>migrate</code> with <code>--entry src/index.ts</code></td><td>Loaded through Node&#39;s type stripping, without tsdown</td><td>The CLI transforms it with the rolldown of tsdown and the app&#39;s <code>tsconfig.json</code> (<a href="/reference/cli#typescript-entries">TypeScript entries</a>); without tsdown the command exits 2 with <code>The entry is TypeScript: install tsdown ^0.23.4 to load it.</code> Install tsdown as a devDependency (<code>npm install --save-dev tsdown</code>) wherever such a command runs. A built entry (<code>dist/index.mjs</code>) needs nothing, so an image that runs it with dev dependencies pruned keeps starting</td></tr></tbody></table><h3 id="stored-types-moved-to-chamvi-store" tabindex="-1">Stored types moved to <code>@chamvi/store</code> <a class="header-anchor" href="#stored-types-moved-to-chamvi-store" aria-label="Permalink to &quot;Stored types moved to `@chamvi/store`&quot;">​</a></h3><p>The shapes the store holds moved from <code>@chamvi/core</code> to the new package <code>@chamvi/store</code>, which core and every store depend on; core does not re-export them. Import these from <code>@chamvi/store</code> (or <code>@chamvi/app</code>, which re-exports both packages) instead of <code>@chamvi/core</code>. The shapes are unchanged.</p><table tabindex="0"><thead><tr><th>Export</th><th>Kind</th></tr></thead><tbody><tr><td><code>Run</code>, <code>RunStatusLiteral</code>, <code>Usage</code>, <code>RunTaint</code></td><td>type</td></tr><tr><td><code>RunStatus</code></td><td>enum</td></tr><tr><td><code>WaitPoint</code>, <code>ApprovalWaitPoint</code>, <code>DispatchWaitPoint</code></td><td>type</td></tr><tr><td><code>ApprovalOption</code></td><td>type</td></tr><tr><td><code>TriggerEnvelope</code>, <code>Invoker</code>, <code>TriggerParent</code>, <code>TriggerSource</code></td><td>type</td></tr><tr><td><code>Artifact</code></td><td>type</td></tr><tr><td><code>Step</code>, <code>Checkpoint</code></td><td>type</td></tr><tr><td><code>AgentRevision</code></td><td>type</td></tr><tr><td><code>Connection</code></td><td>type</td></tr><tr><td><code>ConversationIdentity</code>, <code>ConversationScope</code>, <code>ConversationBinding</code></td><td>type</td></tr><tr><td><code>ConversationItem</code>, <code>ConversationNote</code>, <code>ConversationNoteSource</code>, <code>ConversationNoteOperation</code>, <code>ConversationSnapshot</code></td><td>type</td></tr><tr><td><code>normalizeEnvelope</code>, <code>normalizeWaitPoint</code></td><td>function</td></tr></tbody></table><p><code>@chamvi/store</code> lists <code>ai</code> as an optional peer dependency, for the <code>ModelMessage</code> of <code>Checkpoint</code> and <code>ConversationSnapshot</code>. It also holds the repository ports, the stored row types (<code>CheckpointRecord</code>, <code>EffectRecord</code>, <code>ArtifactRecord</code>, <code>StateEntry</code>, <code>StateDocument</code>, <code>StateDocumentPage</code>, <code>Lock</code>, <code>IdempotencyKey</code>, <code>AgentRevisionRecord</code>, <code>ConnectionRecord</code>, <code>ConnectionEntryRecord</code>, <code>ConnectionSecretRecord</code>, <code>ConversationRecord</code>, <code>ConversationItemRecord</code>, <code>ConversationNoteRecord</code>, <code>ConversationOperationRecord</code>) and the storage errors.</p><h3 id="services-in-place-of-the-store-aggregate" tabindex="-1">Services in place of the store aggregate <a class="header-anchor" href="#services-in-place-of-the-store-aggregate" aria-label="Permalink to &quot;Services in place of the store aggregate&quot;">​</a></h3><p>The store aggregate is gone: <code>IStore</code>, <code>createMemoryStore()</code> and <code>MemoryStoreOptions</code> (<code>@chamvi/core</code>), <code>createDatabaseStore()</code>, <code>DatabaseStoreOptions</code> and <code>DatabaseStore</code> (<code>@chamvi/store-db</code>), <code>EngineOptions.store</code>, <code>IEngine.store</code> (<code>engine.store</code>) and <code>AppToken.STORE</code> (<code>@chamvi/app</code>) are removed.</p><p>Every rule lives in a service of <code>@chamvi/core</code>, each over the repository ports of <code>@chamvi/store</code> that only store and read. <code>new Engine()</code> takes each service by name and exposes it as a property of the engine.</p><table tabindex="0"><thead><tr><th>Service (engine option and property)</th><th>Ports (<code>@chamvi/store</code>)</th><th>Memory (<code>@chamvi/store-memory</code>, <code>{ registry }</code>)</th><th>PostgreSQL (<code>@chamvi/store-db</code>, <code>(dataSource)</code>)</th></tr></thead><tbody><tr><td><code>RunService</code> (<code>runService</code>, required)</td><td><code>IRunRepository</code></td><td><code>MemoryRunRepository</code></td><td><code>DatabaseRunRepository</code></td></tr><tr><td><code>StepService</code> (<code>stepService</code>, required)</td><td><code>IStepRepository</code></td><td><code>MemoryStepRepository</code></td><td><code>DatabaseStepRepository</code></td></tr><tr><td><code>CheckpointService</code> (<code>checkpointService</code>, required)</td><td><code>ICheckpointRepository</code></td><td><code>MemoryCheckpointRepository</code></td><td><code>DatabaseCheckpointRepository</code></td></tr><tr><td><code>EffectService</code> (<code>effectService</code>, required)</td><td><code>IEffectRepository</code></td><td><code>MemoryEffectRepository</code></td><td><code>DatabaseEffectRepository</code></td></tr><tr><td><code>ArtifactService</code> (<code>artifactService</code>, required)</td><td><code>IArtifactRepository</code></td><td><code>MemoryArtifactRepository</code></td><td><code>DatabaseArtifactRepository</code></td></tr><tr><td><code>StateService</code> (<code>stateService</code>, required)</td><td><code>IStateRepository</code>, <code>IStateDocumentRepository</code></td><td><code>MemoryStateRepository</code>, <code>MemoryStateDocumentRepository</code></td><td><code>DatabaseStateRepository</code>, <code>DatabaseStateDocumentRepository</code></td></tr><tr><td><code>LockService</code> (<code>lockService</code>, required)</td><td><code>ILockRepository</code></td><td><code>MemoryLockRepository</code></td><td><code>DatabaseLockRepository</code></td></tr><tr><td><code>IdempotencyService</code> (<code>idempotencyService</code>, required)</td><td><code>IIdempotencyRepository</code></td><td><code>MemoryIdempotencyRepository</code></td><td><code>DatabaseIdempotencyRepository</code></td></tr><tr><td><code>AgentRevisionService</code> (<code>agentRevisionService</code>, required)</td><td><code>IAgentRevisionRepository</code></td><td><code>MemoryAgentRevisionRepository</code></td><td><code>DatabaseAgentRevisionRepository</code></td></tr><tr><td><code>ConnectionService</code> (<code>connectionService</code>, optional; the engine only exposes it)</td><td><code>IConnectionRepository</code> with <code>entries</code>, <code>secrets</code></td><td><code>MemoryConnectionRepository</code></td><td><code>DatabaseConnectionRepository</code></td></tr><tr><td><code>ConversationService</code> (<code>conversationService</code>, optional; required by <code>conversations</code>)</td><td><code>IConversationRepository</code> with <code>items</code>, <code>notes</code>, <code>operations</code></td><td><code>MemoryConversationRepository</code></td><td><code>DatabaseConversationRepository</code></td></tr></tbody></table><p>Build every memory repository on one <code>MemoryRegistry</code>: it enforces the references the database&#39;s foreign keys do, and the connection fence reads the lock rows there. Specs and examples build all of it with <code>createTestEngine()</code> of <code>@chamvi/test-kit</code> (an engine on memory repositories, <code>replicaOf</code> for a second replica on the same services); an app gets it from <code>@chamvi/app</code> (below).</p><table tabindex="0"><thead><tr><th>Before</th><th>Replacement</th></tr></thead><tbody><tr><td><code>new Engine({ store: createMemoryStore({ clock }), agents })</code></td><td><code>new Engine({ runService, stepService, checkpointService, effectService, artifactService, stateService, lockService, idempotencyService, agentRevisionService, connectionService?, conversationService?, agents })</code>, each service on its repository (see <a href="/repositories/memory">Memory repositories</a> and <a href="/repositories/database">Database store</a>)</td></tr><tr><td><code>engine.store.runs.insert(run)</code></td><td><code>engine.runService.create(run)</code> (resolves <code>false</code> for a stored id, as before)</td></tr><tr><td><code>engine.store.runs.findOne</code>, <code>findOneOrFail</code>, <code>update</code>, <code>find</code>, <code>findOrFail</code>, <code>claim</code>, <code>renewClaim</code></td><td>The same methods on <code>engine.runService</code>; <code>runService.list(query)</code> also takes a rapiq query</td></tr><tr><td><code>engine.store.steps.insert(step)</code>, <code>find</code>, <code>findOrFail</code></td><td><code>engine.stepService.create(step)</code>, <code>find</code>, <code>findOrFail</code></td></tr><tr><td><code>engine.store.checkpoints.save</code>, <code>findOne</code>, <code>findOneOrFail</code></td><td>The same methods on <code>engine.checkpointService</code>; <code>save</code> resolves the checkpoint the run holds afterwards</td></tr><tr><td><code>engine.store.effects.findOne</code>, <code>findOneOrFail</code>, <code>save</code></td><td>The same methods on <code>engine.effectService</code>; <code>save</code> resolves <code>{ result }</code></td></tr><tr><td><code>engine.store.artifacts.insert(artifact, data, key?)</code></td><td><code>engine.artifactService.create(artifact, data, key?)</code> (resolves <code>false</code> when the id, or the key in the run, is taken)</td></tr><tr><td><code>engine.store.artifacts.save</code>, <code>findOne</code>, <code>findOneOrFail</code>, <code>findOneByKey</code>, <code>read</code>, <code>find</code>, <code>findOrFail</code></td><td>The same methods on <code>engine.artifactService</code></td></tr><tr><td><code>engine.store.state.findOne</code>, <code>findOneOrFail</code>, <code>set</code>, <code>find</code>, <code>findOrFail</code>, <code>findDocuments</code>, <code>findDocumentsOrFail</code>, <code>upsertDocument</code>, <code>deleteDocument</code></td><td>The same methods on <code>engine.stateService</code> (<code>set</code> resolves the stored value, <code>upsertDocument</code> <code>{ id, doc }</code>), plus <code>list(agent, query)</code> and <code>listDocuments(agent, collection, query)</code></td></tr><tr><td><code>engine.store.locks.acquire</code>, <code>renew</code>, <code>release</code>, <code>purgeExpired</code></td><td>The same methods on <code>engine.lockService</code>, plus <code>holds(key, owner)</code>; <code>purgeExpired</code> resolves the number of rows deleted, on memory too</td></tr><tr><td><code>engine.store.idempotency.claim</code>, <code>purgeExpired</code></td><td>The same methods on <code>engine.idempotencyService</code></td></tr><tr><td><code>engine.store.agentRevisions.findOne</code>, <code>save</code>, <code>delete</code>, <code>find</code></td><td>The same methods on <code>engine.agentRevisionService</code> (plus the <code>OrFail</code> forms); <code>save</code> resolves the stored marker</td></tr><tr><td><code>engine.store.connections.insert(connection)</code></td><td><code>engine.connectionService.create(connection)</code> (resolves <code>false</code> for a taken name)</td></tr><tr><td><code>engine.store.connections.findOne</code>, <code>findOneOrFail</code>, <code>find</code>, <code>delete</code>, <code>replace</code>, <code>findEntry</code>, <code>findEntries</code>, <code>writeEntries</code></td><td>The same methods on <code>engine.connectionService</code></td></tr><tr><td><code>engine.store.conversations.resolve</code>, <code>beginTurn</code>, <code>endTurn</code>, <code>prepareEmit</code>, <code>confirmEmit</code>, <code>pendingEmits</code>, <code>findItems</code>, <code>findNotes</code>, <code>findOneNote</code>, <code>applyNote</code>, <code>reset</code>, <code>delete</code>, <code>prune</code> and the <code>OrFail</code> forms</td><td>The same methods on <code>engine.conversationService</code></td></tr><tr><td><code>IConversations.repository</code> (the engine&#39;s conversation capability)</td><td><code>IConversations.service</code>, the <code>ConversationService</code></td></tr><tr><td><code>IRunRepository</code>, <code>IStepRepository</code>, <code>ICheckpointRepository</code>, <code>IEffectRepository</code>, <code>IArtifactRepository</code>, <code>IStateRepository</code>, <code>ILockRepository</code>, <code>IIdempotencyRepository</code>, <code>IAgentRevisionRepository</code>, <code>IConnectionRepository</code>, <code>IConversationRepository</code> from <code>@chamvi/core</code></td><td>The ports of the same names from <code>@chamvi/store</code> (each the generic entity port, see <a href="#writing-a-third-party-store">Writing a third-party store</a>), plus <code>IStateDocumentRepository</code>; <code>RunFindOptions</code>, <code>RunUpdateOptions</code>, <code>StateFindOptions</code>, <code>StateDocumentFindOptions</code> stay in <code>@chamvi/core</code></td></tr><tr><td><code>MemoryRunRepository</code>, <code>MemoryStepRepository</code>, ..., <code>MemoryConnectionRepository({ clock?, holdsLock })</code>, <code>MemoryConversationRepository({ clock?, hasRun? })</code> from <code>@chamvi/core</code>, <code>MemoryRunReferenceOptions</code>, <code>MemoryConversationRepositoryOptions</code></td><td>The <code>Memory*Repository</code> classes of <code>@chamvi/store-memory</code>, each <code>new ...({ registry })</code>; the clock belongs to the services</td></tr><tr><td><code>new DatabaseRunRepository({ dataSource, clock? })</code> and the other database repositories with options</td><td><code>new DatabaseRunRepository(dataSource)</code> and the others with the data source alone</td></tr><tr><td><code>@chamvi/core/conversation/persistence</code> (the shared policy for custom stores)</td><td>Removed: the policy belongs to <code>ConversationService</code></td></tr><tr><td><code>createAgentState(agent, schema, store.state)</code>, <code>wrapToolsForRun(tools, ctx, store.effects)</code>, <code>findApprovalWaitBelow(store.runs, run)</code></td><td><code>createAgentState(agent, schema, engine.stateService)</code>, <code>wrapToolsForRun(tools, ctx, engine.effectService)</code>, <code>findApprovalWaitBelow(engine.runService, run)</code></td></tr><tr><td><code>createConnectionVault({ store, keyring, clock? })</code></td><td><code>createConnectionVault({ connectionService, lockService, keyring, clock? })</code>; without a connection service it throws <code>InvalidAgentDefinitionError</code></td></tr><tr><td><code>createRepositoryScheduleLock(store.locks, owner)</code> (<code>@chamvi/channel-cron</code>)</td><td><code>createRepositoryScheduleLock(engine.lockService, owner)</code></td></tr><tr><td><code>githubChannel({ app, locks? })</code> (<code>@chamvi/github</code>) with <code>store.locks</code> or a channel-local memory lock</td><td><code>locks</code> is required, a <code>LockService</code> (or a <code>Pick</code> of <code>acquire</code> and <code>release</code>): <code>githubChannel({ app, locks: engine.lockService })</code>; <code>githubModule()</code> passes <code>AppToken.LOCK_SERVICE</code></td></tr><tr><td><code>createKnowledge({ locks: store.locks })</code> (<code>@chamvi/knowledge</code>)</td><td><code>createKnowledge({ locks: engine.lockService })</code>; <code>knowledgeModule()</code> takes <code>AppToken.LOCK_SERVICE</code></td></tr></tbody></table><h3 id="chamvi-app-the-store-module-and-the-tokens" tabindex="-1"><code>@chamvi/app</code>: the store module and the tokens <a class="header-anchor" href="#chamvi-app-the-store-module-and-the-tokens" aria-label="Permalink to &quot;`@chamvi/app`: the store module and the tokens&quot;">​</a></h3><p><code>storeModule()</code> registers the repositories: the database repositories over <code>DATABASE_URL</code> (or a given data source), else memory repositories on one registry. In the same setup step the app builds every service from the registered repositories and registers each under a token of its own; the engine module passes them to the engine, and the lock and idempotency services get the hourly purge (<code>CHAMVI_PURGE_INTERVAL_MS</code>), on memory too.</p><table tabindex="0"><thead><tr><th>Before</th><th>Replacement</th></tr></thead><tbody><tr><td><code>storeModule({ store, url?, dataSource? })</code>, <code>StoreModuleOptions</code> with <code>store</code></td><td><code>storeModule({ url?, dataSource? })</code></td></tr><tr><td><code>AppToken.STORE</code></td><td>A token per repository and per service: <code>RUN_REPOSITORY</code>, <code>RUN_SERVICE</code>, <code>STEP_REPOSITORY</code>, <code>STEP_SERVICE</code>, <code>CHECKPOINT_REPOSITORY</code>, <code>CHECKPOINT_SERVICE</code>, <code>EFFECT_REPOSITORY</code>, <code>EFFECT_SERVICE</code>, <code>ARTIFACT_REPOSITORY</code>, <code>ARTIFACT_SERVICE</code>, <code>STATE_REPOSITORY</code>, <code>STATE_DOCUMENT_REPOSITORY</code>, <code>STATE_SERVICE</code>, <code>LOCK_REPOSITORY</code>, <code>LOCK_SERVICE</code>, <code>IDEMPOTENCY_REPOSITORY</code>, <code>IDEMPOTENCY_SERVICE</code>, <code>AGENT_REVISION_REPOSITORY</code>, <code>AGENT_REVISION_SERVICE</code>, and, while the store keeps them, <code>CONNECTION_REPOSITORY</code>, <code>CONNECTION_SERVICE</code>, <code>CONVERSATION_REPOSITORY</code>, <code>CONVERSATION_SERVICE</code>; <code>STORE_KIND</code> says where the rows live (<code>memory</code> or <code>database</code>)</td></tr><tr><td>A module asked <code>container.resolve(AppToken.STORE).connections !== undefined</code></td><td>It asks <code>container.has(AppToken.CONNECTION_SERVICE)</code></td></tr><tr><td>A module replacing the store module (<code>ModuleName.STORE</code>) registered <code>AppToken.STORE</code></td><td>It registers the repository tokens and, if it likes, <code>STORE_KIND</code>; the app builds the services (see <a href="#writing-a-third-party-store">Writing a third-party store</a>)</td></tr><tr><td><code>migrateStore()</code> and <code>assertStoreNotLegacy()</code> (<code>@chamvi/store-db</code>) threw a <code>ChamviError</code> (code <code>store_legacy_schema</code>)</td><td><code>LegacySchemaError</code> of <code>@chamvi/store-db</code> (an ebec <code>BaseError</code>, the same code and message); <code>@chamvi/store-db</code> has no <code>@chamvi/core</code> peer dependency any more</td></tr></tbody></table><p><code>@chamvi/app/testing</code> adds <code>memoryStoreModule({ registry?, connections?, conversations? })</code>: the built-in memory store on a given <code>MemoryRegistry</code> (a second app on the same registry sees the rows of the first), without the connection or conversation repository when the flag is <code>false</code>. A spec reaches a repository or a service through its token on the harness&#39;s container.</p><h3 id="a-database-for-an-app-s-own-tables" tabindex="-1">A database for an app&#39;s own tables <a class="header-anchor" href="#a-database-for-an-app-s-own-tables" aria-label="Permalink to &quot;A database for an app&#39;s own tables&quot;">​</a></h3><p>New in <code>@chamvi/app</code>: <code>databaseModule({ entities, migrations, migrationsDirectory, migrationsTableName, name? })</code>, <code>dataSourceToken(name?)</code>, <code>DatabaseToken</code>, <code>readDatabaseDescriptors(app)</code> and <code>APP_MODULES</code> (the symbol an App lists its modules under); in <code>@chamvi/store-db</code>: <code>buildDatabaseOptions</code>, <code>connectDatabase</code>, <code>synchronizeDatabase</code>, <code>closeDatabase</code>, <code>migrateDatabase</code>, <code>pendingDatabaseMigrations</code>, <code>findUntypedColumns</code>, <code>queueDataSource</code>, <code>DatabaseDriverMissingError</code>, <code>DatabaseOptionsError</code> and <code>DatabaseBusyError</code>. See <a href="/guide/database">Database</a> and, for specs, <a href="/guide/testing#an-app-s-database">Testing</a>. On SQLite the module&#39;s data source takes one statement, transaction or whole operation at a time on its one connection; inside a transaction opened by hand on a query runner use that runner or its manager, and end it: work that waits 30 seconds (<code>databaseModule({ waitTimeoutMs })</code> changes it) behind one open transaction, or an operation that does not return, is refused with <code>DatabaseBusyError</code> (its <code>holder</code> says which). <code>connectDatabase(options, queue?)</code> takes the same wait limit and clock. New in <code>@chamvi/store-db</code> for <code>chamvi migration</code>: <code>runMigrationOperation</code>, <code>isSameDatabase</code>, <code>MIGRATION_OPERATIONS</code>, <code>STORE_DATABASE</code>, <code>MIGRATION_DATABASE_URL_VARIABLE</code> and <code>DATABASE_LOCK_PREFIX</code>; <code>migrateDatabase</code> resolves with the names of the migrations it ran; <code>databaseModule</code> refuses the name <code>store</code>. A <code>drained</code> lifecycle hook now runs also when the engine&#39;s drain failed. An app without a database module is unchanged. Without <code>DATABASE_URL</code> the module needs the optional peer <code>better-sqlite3</code>.</p><p>List endpoints and test support for it, new: <code>defineSchema()</code>, <code>decodeQuery()</code> and <code>scopeQuery()</code> in <code>@chamvi/http</code> (re-exported by <code>@chamvi/app</code>), with the types <code>ListSchema</code>, <code>ListSchemaOptions</code>, <code>ListSchemaEntity</code>, <code>ListSchemaKey</code>, <code>ListFilterOperator</code> and <code>ListSortDirection</code>; <code>databaseModule({ schemas })</code> checks each schema against its entity at start; in <code>@chamvi/store-db</code>: <code>applyQuery</code>, <code>validateEntitySchemas</code>, <code>dateToISOStringTransformer</code> and the types <code>ApplyQueryOptions</code>, <code>ApplyQueryResult</code>, <code>EntityListSchema</code>; <code>migrateStore</code> resolves with the names of the migrations it ran; in <code>@chamvi/test-kit</code>: <code>createTestDataSource({ entities, url? })</code> with the type <code>TestDataSourceOptions</code> (on its first call it loads <code>typeorm</code> and the driver, optional peers, and <code>@chamvi/store-db</code>, which is in no dependency field of the kit: it is resolved from the kit, then from the app&#39;s folder, so the app lists it in its devDependencies). A service spec runs on <code>MemoryEntityRepository</code> of <code>@chamvi/store-memory</code> (its new option <code>dates</code> filters a date field as the instant a value names, as a database date column is filtered; on both a value naming no instant is refused with <code>EntityQueryError</code>); there is no fake repository.</p><h3 id="writing-a-third-party-store" tabindex="-1">Writing a third-party store <a class="header-anchor" href="#writing-a-third-party-store" aria-label="Permalink to &quot;Writing a third-party store&quot;">​</a></h3><p>Implement each port of <code>@chamvi/store</code> on your storage. A port is the generic entity port <code>IEntityRepository&lt;T&gt;</code> on the port&#39;s stored type, plus at most one finder (<code>IRunRepository.findByWaitKind</code>, <code>IStateDocumentRepository.findContaining</code>, <code>IArtifactRepository.readData</code>, <code>ILockRepository</code> and <code>IIdempotencyRepository</code> <code>removeExpiredBy(time)</code>, <code>IConnectionRepository.findFence</code>) and the child repositories of connections and conversations, bound to the parent&#39;s transaction. A repository decides nothing: no status or owner compare, limit, default, time stamp or choice of error.</p><ul><li><code>findMany(query)</code> runs a rapiq query (fields, filters, sorts, pagination) and resolves <code>{ data, meta: { total, limit?, offset? } }</code>; with a field selection it reads those fields only. A row it read with a field selection is refused by <code>upsert</code> and <code>upsertMany</code> (it would clear the other columns); <code>save</code> of it writes only what changed.</li><li><code>findOneById</code>, <code>findOneBy(where)</code>, <code>findManyBy(where)</code>: an <code>EntityWhere&lt;T&gt;</code> holds a value, <code>null</code> or an array of values (any of) per property; inside <code>transaction(fn)</code> a single-row read locks the row until the transaction ends.</li><li><code>create</code> and <code>merge</code> store nothing; <code>save</code> inserts an object <code>create()</code> returned and updates one a read returned (its changed properties only), decided by object identity.</li><li><code>upsert</code>, <code>upsertMany(entities)</code> (one transaction, in as few statements as the storage allows, a later entity of a key replaces an earlier one), <code>remove</code>, <code>removeMany</code>, <code>removeManyBy(where)</code> (one statement, resolves the count, never an empty where), <code>validateRelations</code>, <code>checkUniqueness</code>, <code>transaction(fn)</code>.</li><li>Six storage errors, each with the entity&#39;s label and a fixed message, never a value: <code>EntityNotFoundError</code> (<code>entity_not_found</code>), <code>EntityConflictError</code> (<code>entity_conflict</code>, a unique key), <code>EntityRelationError</code> (<code>entity_relation_invalid</code>, a missing referenced row), <code>EntityDeadlockError</code> (<code>entity_deadlock</code>), <code>EntityQueryError</code> (<code>entity_query_invalid</code>: a where with a property set to <code>undefined</code>, <code>findOneById(undefined)</code>, <code>removeManyBy({})</code>, an upsert of a field-selected row, an operation a port does not offer such as a step upsert), <code>EntityInvalidError</code> (<code>entity_invalid</code>: a value the table refuses, such as a missing required column, a failed check or a value too long; it names the operation and the column or constraint, never the value).</li><li><code>ConversationItemRecord.bytes</code> is the UTF-8 byte length of the item&#39;s text, set by <code>ConversationService</code>; a repository stores and returns it as given (the recall selects by it, reading <code>id</code> and <code>bytes</code> only, then the text of the selected items).</li></ul><p><code>MemoryEntityRepository</code> (<code>@chamvi/store-memory</code>) and <code>EntityRepositoryAdapter</code> (<code>@chamvi/store-db</code>, for a TypeORM driver) implement all of it; a repository built on either implements only its mapping. Prove each port with its suite of <code>@chamvi/test-kit</code>: <code>describeEntityRepositoryContract</code> and <code>describeRunRepositoryContract</code>, <code>describeStepRepositoryContract</code>, <code>describeCheckpointRepositoryContract</code>, <code>describeEffectRepositoryContract</code>, <code>describeArtifactRepositoryContract</code>, <code>describeStateRepositoryContract</code>, <code>describeLockRepositoryContract</code>, <code>describeIdempotencyRepositoryContract</code>, <code>describeAgentRevisionRepositoryContract</code>, <code>describeConnectionRepositoryContract</code>, <code>describeConversationRepositoryContract({ name, create, untilBlocked })</code>. Then give <code>@chamvi/app</code> a module named <code>ModuleName.STORE</code> that registers each repository token (<code>RUN_REPOSITORY</code>, <code>STEP_REPOSITORY</code>, <code>CHECKPOINT_REPOSITORY</code>, <code>EFFECT_REPOSITORY</code>, <code>ARTIFACT_REPOSITORY</code>, <code>STATE_REPOSITORY</code>, <code>STATE_DOCUMENT_REPOSITORY</code>, <code>LOCK_REPOSITORY</code>, <code>IDEMPOTENCY_REPOSITORY</code>, <code>AGENT_REVISION_REPOSITORY</code>; <code>CONNECTION_REPOSITORY</code> and <code>CONVERSATION_REPOSITORY</code> optional): it replaces the built-in one, and the app builds the services. A missing required token fails the setup with <code>InvalidAgentDefinitionError</code> naming it.</p><table tabindex="0"><thead><tr><th>Before</th><th>Replacement</th></tr></thead><tbody><tr><td><code>describeRepositoryContract((clock) =&gt; store)</code>, <code>RepositoryContractStore</code></td><td>The suite per port listed above, and the services&#39; own specs for the rules</td></tr><tr><td><code>describeConversationRepositoryContract((clock) =&gt; repository)</code> (the conversation rules)</td><td><code>describeConversationRepositoryContract({ name, create, untilBlocked })</code>, <code>create</code> resolving <code>{ repository, runs, checkpoints }</code>: storage behaviour only</td></tr></tbody></table><h3 id="behaviour-changes" tabindex="-1">Behaviour changes <a class="header-anchor" href="#behaviour-changes" aria-label="Permalink to &quot;Behaviour changes&quot;">​</a></h3><ul><li>A read leaves out a property set to <code>undefined</code> (the memory store kept the key with an <code>undefined</code> value): <code>toMatchObject({ claim: undefined })</code> on a read run fails, <code>not.toHaveProperty(&#39;claim&#39;)</code> holds.</li><li>Every change reads its row locked first and then the clock: a lease renewal that waited for the row compares a fresh time. A test that moves a <code>ControllableClock</code> by a whole <code>claimTtlMs</code> at once loses the lease of a running run; move it in steps so the renewals run.</li><li><code>effectService.save(key, undefined)</code> stores <code>null</code> on memory too. <code>findDocuments</code> lists by document id in code-point order on memory too, and its <code>where</code> matches a top-level value when it is deeply equal on both drivers: PostgreSQL used containment (<code>{ tags: [&#39;a&#39;] }</code> matched <code>tags: [&#39;a&#39;, &#39;b&#39;]</code>), memory compared with <code>===</code> (a nested value never matched).</li><li>The purge of expired locks and idempotency keys (<code>CHAMVI_PURGE_INTERVAL_MS</code>) runs on a memory store too.</li><li>A background component whose stop does not settle within <code>CHAMVI_DRAIN_TIMEOUT_MS</code> is logged, the shutdown goes on to the drain, and <code>stop()</code> rejects with <code>app_stop_failed</code> (the CLI exits 1). The components&#39; stop and the drain share that one budget: the drain gets what the stop left, so the shutdown takes no longer than before.</li><li>A start (or <code>run-job</code>) with <code>CHAMVI_MIGRATE=false</code> on a store with pending migrations fails with <code>store_not_migrated</code>, naming how many are pending, and writes nothing (it started and failed on the first write to a missing column): run <code>chamvi migrate</code> before the app starts.</li><li>On PostgreSQL a held lock or a claimed idempotency key is refused on one <code>SELECT</code>; acquiring a free lock or claiming a fresh key takes four statements (it took one), a renewal or release four, a takeover of an expired lease or key five.</li><li>Connections: a fenced write (an entry batch, a replace, a fenced delete) locks the connection row, then reads the lease&#39;s lock row locked, then the clock; on memory a takeover, renewal or release of the lease in flight is waited for as on PostgreSQL. <code>writeEntries</code> on an absent connection is <code>RepositoryNotFoundError</code> on both stores (PostgreSQL answered <code>LeaseLostError</code>). On PostgreSQL an entry batch is one upsert statement per chunk of rows, and a clear, replace or delete removes the entries and secrets with one <code>DELETE</code> each.</li><li>Conversations: every change reads the conversation row locked first (PostgreSQL <code>FOR NO KEY UPDATE</code>), then the clock. A memory run or checkpoint bound to a conversation scope the store does not hold is refused with <code>EntityRelationError</code> as on PostgreSQL. <code>beginTurn</code> of a malformed run id while another run holds the turn answers <code>busy</code> on both stores (PostgreSQL threw <code>RunNotFoundError</code>). Memory scope ids are uuid v7 as on PostgreSQL; the identity&#39;s digest is the row&#39;s unique <code>key</code>. <code>resolve</code> is insert-if-absent: it never revives a deleted generation. The recall reads the sizes of the sent items first and the text of the selected items only; its result is unchanged.</li></ul><h3 id="the-http-api-on-the-services" tabindex="-1">The HTTP API on the services <a class="header-anchor" href="#the-http-api-on-the-services" aria-label="Permalink to &quot;The HTTP API on the services&quot;">​</a></h3><p><code>createHttpApp({ engine })</code> reads everything through the engine&#39;s services (<code>engine.runService</code>, <code>engine.stateService</code>, ...; the connection configurations through <code>engine.connectionService</code>, so <code>connectionConfigs</code> needs an engine with a connection service). Routes, requests and answers are unchanged, except that a storage error reaching a route is no longer a 500: it answers with its code and a fixed message, never the error&#39;s own: <code>404 entity_not_found</code>, <code>409 entity_conflict</code>, <code>400 entity_relation_invalid</code>, <code>400 entity_query_invalid</code>, <code>400 entity_invalid</code>, <code>409 entity_deadlock</code>, <code>503 database_unavailable</code> (<code>@chamvi/store-db</code>&#39;s <code>DatabaseUnavailableError</code>, reported to <code>onError</code> as every 5xx). The run listing orders runs the sorts leave equal by <code>id</code> (<code>createdAt</code>, then <code>id</code>, without sorts).</p><h3 id="new-variables" tabindex="-1">New variables <a class="header-anchor" href="#new-variables" aria-label="Permalink to &quot;New variables&quot;">​</a></h3><p>Each is optional and names a field of a named instance; the default instance keeps its variables.</p><table tabindex="0"><thead><tr><th>Variables</th><th>Read by</th></tr></thead><tbody><tr><td><code>CHAMVI_GITHUB_&lt;NAME&gt;_APP_ID</code>, <code>_APP_PRIVATE_KEY</code>, <code>_WEBHOOK_SECRET</code>, <code>_INSTALLATION_ID</code>, <code>_APP_SLUG</code>, <code>_API_URL</code></td><td><code>githubModule({ name })</code></td></tr><tr><td><code>CHAMVI_DISCORD_*</code>, <code>CHAMVI_DISCORD_&lt;NAME&gt;_*</code></td><td><a href="/deployment/discord#with-chamvi-app"><code>discordModule()</code></a></td></tr></tbody></table><h3 id="steps" tabindex="-1">Steps <a class="header-anchor" href="#steps" aria-label="Permalink to &quot;Steps&quot;">​</a></h3><ol><li>Add <code>chatWhatsappUiModule()</code> if the app uses <code>whatsappModule()</code>, and the other <code>*-ui</code> modules for the connections you want to configure in the dashboard.</li><li>Set <code>CHAMVI_ENCRYPTION_KEYS</code> if the dashboard will save connections.</li><li>A dashboard not at <code>/ui</code>: pass the same value as <code>uiBase</code> to every <code>*-ui</code> module.</li><li>Replace any reference to the old GitHub module id.</li><li>Drain the app before the upgrade, so no stored run carries an invoker with old permission strings; rewrite <code>CHAMVI_TOKENS</code> and the authup roles (<a href="/guide/permissions#upgrading">Permissions and authup</a>).</li><li>Stop every replica of the previous version, then run the migrations (a default start or <code>chamvi migrate</code>) before the app serves: on a large conversation items table the byte-length backfill holds that table&#39;s lock for its duration (above).</li><li>Code that builds an engine by hand or reads the store aggregate: move to the services (<a href="#services-in-place-of-the-store-aggregate">Services in place of the store aggregate</a>); a custom store: <a href="#writing-a-third-party-store">Writing a third-party store</a>.</li></ol><h2 id="upgrading-to-0-8" tabindex="-1">Upgrading to 0.8 <a class="header-anchor" href="#upgrading-to-0-8" aria-label="Permalink to &quot;Upgrading to 0.8&quot;">​</a></h2><p>The Postgres store (<code>@chamvi/store-db</code>) now gives every table a single <code>id</code> primary key, a time-ordered UUID v7 (the append-only steps and conversation items use a bigint). Run ids, artifact ids and, in Postgres, conversation scope ids are UUIDs. The eight earlier migrations are replaced by one baseline migration, and <strong>an existing database cannot be upgraded in place: the new version needs a new, empty database.</strong> The in-memory store is unaffected.</p><h3 id="breaking-changes-2" tabindex="-1">Breaking changes <a class="header-anchor" href="#breaking-changes-2" aria-label="Permalink to &quot;Breaking changes&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Change</th><th>Before</th><th>Replacement</th></tr></thead><tbody><tr><td>Database</td><td>Schema built by the eight earlier migrations</td><td>A new, empty database; the baseline <code>UuidBaseline1794096000000</code> creates the schema. Runs, steps, state, documents, artifacts and conversation memory of the old database are not carried over</td></tr><tr><td><code>migrateStore(dataSource)</code> on an old database</td><td>Applied the pending migrations</td><td>Refuses it before changing anything, with an error (code <code>store_legacy_schema</code>) that names this guide</td></tr><tr><td><code>chamvi start --check</code> on an old database</td><td>Exit 0 (with the default <code>CHAMVI_MIGRATE=true</code>)</td><td>Exit 1 with the same message, whatever <code>CHAMVI_MIGRATE</code> says</td></tr><tr><td>Run and artifact ids</td><td>Run ids from <code>randomUUID()</code>; artifact ids <code>&lt;runId&gt;.0000</code> for attachments and <code>&lt;runId&gt;.k.&lt;hash&gt;</code> for keyed puts</td><td>UUID v7 for both. Treat ids as opaque strings. A keyed <code>artifacts.put({ key })</code> keeps its stored id when a later put replaces it</td></tr><tr><td><code>keyedArtifactId()</code> (<code>@chamvi/core</code>)</td><td>Exported</td><td>Removed. <code>IArtifactRepository.insert(artifact, data, key?)</code> and <code>save(artifact, data, key)</code> take a private key; <code>findOneByKey(runId, key)</code> looks one up. A custom store must implement them (<code>describeRepositoryContract()</code> checks it)</td></tr><tr><td>Malformed ids in the HTTP API</td><td>n/a</td><td>A run or artifact id that is not a UUID is a 404 on the database store, as for any unknown id</td></tr></tbody></table><h3 id="steps-1" tabindex="-1">Steps <a class="header-anchor" href="#steps-1" aria-label="Permalink to &quot;Steps&quot;">​</a></h3><ol><li>Create a new, empty Postgres database (a new database, not a new schema in the old one, keeps the rollback below simple).</li><li>Drain the old deployment: stop ingress and run-job CronJobs, and let in-flight runs settle or answer their approvals. Nothing from the old database is read by the new version.</li><li>Point <code>DATABASE_URL</code> at the new database and deploy the new version. With the default <code>CHAMVI_MIGRATE=true</code> the first start creates the schema; with <code>CHAMVI_MIGRATE=false</code>, run <code>chamvi migrate</code> first.</li><li>Check before switching traffic: <code>chamvi start --check</code> with the new <code>DATABASE_URL</code> exits 0. Pointed at the old database it exits 1 and prints the message that names this guide.</li></ol><p>The old database is left untouched. To roll back, redeploy the previous chamvi version with the old <code>DATABASE_URL</code>; the old schema and its data are intact. Keep it for as long as you may need that, and drop it when you do not.</p><p>The check that refuses an old database covers <code>migrateStore()</code> (so a default start and <code>chamvi migrate</code>), <code>chamvi start --check</code> and a start with <code>CHAMVI_MIGRATE=false</code>. Each exits 1 with the same message.</p><p>The check is temporary: the chamvi version after this one removes it, and an old database then fails on <code>CREATE TABLE</code> with a raw Postgres error instead.</p><h2 id="upgrading-to-0-7" tabindex="-1">Upgrading to 0.7 <a class="header-anchor" href="#upgrading-to-0-7" aria-label="Permalink to &quot;Upgrading to 0.7&quot;">​</a></h2><h3 id="breaking-changes-3" tabindex="-1">Breaking changes <a class="header-anchor" href="#breaking-changes-3" aria-label="Permalink to &quot;Breaking changes&quot;">​</a></h3><p><a href="/guide/dispatch#simple-agents">Simple agents</a> (<code>defineSimpleAgent({ run })</code>, no model) and <a href="/guide/dispatch#generated-dispatch-tools">generated dispatch tools</a> arrived (<a href="https://github.com/chamvi/chamvi/issues/131" target="_blank" rel="noreferrer">#131</a>).</p><table tabindex="0"><thead><tr><th>Change</th><th>Before (0.6)</th><th>Replacement (0.7)</th></tr></thead><tbody><tr><td><code>defineAgent()</code></td><td>Builds every agent</td><td>Removed: <code>defineModelAgent()</code> takes the same input and runs the same checks (rename the call). A definition with <code>run</code> is refused there: build it with <code>defineSimpleAgent()</code></td></tr><tr><td><code>Agent</code></td><td><code>{ name, definition }</code></td><td>A union of <code>ModelAgent</code> and <code>SimpleAgent</code>, told apart by <code>agent.kind</code> (<code>&#39;model&#39;</code> or <code>&#39;simple&#39;</code>), which narrows <code>agent.definition</code> as well. An agent built by hand needs <code>kind</code>: the engine refuses one whose <code>kind</code> is neither or disagrees with its definition. A folder or package agent built by an older core (no <code>kind</code>) loads as a model agent</td></tr><tr><td><code>AgentDefinition</code></td><td>One shape, <code>instructions</code> required</td><td>A union of <code>ModelAgentDefinition</code> and <code>SimpleAgentDefinition</code>: on the union, <code>agent.definition.instructions</code>, <code>model</code>, <code>output</code>, <code>conversation</code> and <code>skills</code> read as possibly <code>undefined</code>, <code>run</code> and <code>description</code> are new. Check <code>agent.kind === &#39;model&#39;</code> before reading the model fields</td></tr><tr><td>Hand-written dispatch tools</td><td>A <code>defineTool()</code> around <code>dispatch()</code> that only forwarded the call</td><td>Still works; <code>dispatchTools({ roles })</code> generates the same tool from the role, with <code>agent.on({ idempotencyKey, concurrencyKey, address, description })</code> deciding what the tool did. The hooks see only the payload: keep the hand-written tool when it derives a key or the address from anything else (the trigger&#39;s <code>receivedAt</code>, the run), or put that value into the payload</td></tr></tbody></table><h2 id="upgrading-to-0-6" tabindex="-1">Upgrading to 0.6 <a class="header-anchor" href="#upgrading-to-0-6" aria-label="Permalink to &quot;Upgrading to 0.6&quot;">​</a></h2><h3 id="breaking-changes-4" tabindex="-1">Breaking changes <a class="header-anchor" href="#breaking-changes-4" aria-label="Permalink to &quot;Breaking changes&quot;">​</a></h3><p>Hand-offs became <a href="/guide/dispatch">dispatch</a>: a tool starts runs of its own or another agent and may wait for them (<a href="https://github.com/chamvi/chamvi/issues/129" target="_blank" rel="noreferrer">#129</a>, <a href="https://github.com/chamvi/chamvi/issues/76" target="_blank" rel="noreferrer">#76</a>). No alias is left for the hand-off names.</p><table tabindex="0"><thead><tr><th>Change</th><th>Before (0.5)</th><th>Replacement (0.6)</th></tr></thead><tbody><tr><td>Subscription</td><td><code>handoff.on(opts?)</code>, at most one per agent, subscription id <code>handoff</code></td><td><code>agent.on(opts?)</code>, one per role; the role is the subscription id, default <code>&#39;default&#39;</code> (<code>DEFAULT_DISPATCH_ROLE</code>). <code>agent.on({ role: &#39;handoff&#39; })</code> keeps the old id (stored runs carry it as <code>trigger.trigger</code>)</td></tr><tr><td>Starting a run</td><td><code>startHandoff(ctx, input)</code></td><td><code>dispatch(ctx, input)</code>; <code>input.role</code> picks the role. <code>dispatchTo(ctx, { agent, ... })</code> reaches another agent</td></tr><tr><td>Types</td><td><code>HandoffInput</code>, <code>HandoffResult</code>, <code>HandoffSubscriber</code>, <code>HandoffSubscriptionOptions</code></td><td><code>DispatchInput</code>, <code>DispatchResult</code>, <code>AgentSubscriber</code>, <code>AgentSubscriptionOptions</code></td></tr><tr><td>Constants</td><td><code>HANDOFF_SUBSCRIPTION_ID</code>, <code>MAX_HANDOFF_DEPTH</code> (1), <code>DEFAULT_MAX_HANDOFFS_PER_RUN</code> (100)</td><td><code>DEFAULT_DISPATCH_ROLE</code>, <code>DEFAULT_DISPATCH_MAX_DEPTH</code> (1, per role through <code>agent.on({ maxDepth })</code>, at most <code>DISPATCH_DEPTH_MAX</code> 8), <code>DEFAULT_MAX_DISPATCHES_PER_RUN</code> (100)</td></tr><tr><td>Per-run limit</td><td><code>maxPerRun</code> counted every hand-off of the run (<code>handoff-count:&lt;runId&gt;</code>)</td><td>Counted per target agent and role (<code>dispatch-count:&lt;runId&gt;:&lt;agent&gt;:&lt;role&gt;</code>)</td></tr><tr><td>Keys</td><td>Effect <code>&lt;runId&gt;:handoff:&lt;hash&gt;</code>, idempotency claim <code>handoff:&lt;key&gt;</code></td><td><code>&lt;runId&gt;:dispatch:&lt;hash&gt;</code> (the hash also covers the agent and the role), <code>dispatch:&lt;role&gt;:&lt;key&gt;</code></td></tr><tr><td>Lineage</td><td><code>trigger.parent: { kind: &#39;handoff&#39;, runId, agent, depth }</code></td><td><code>{ kind: &#39;dispatch&#39;, runId, agent, role, depth }</code>, plus <code>run.parentRunId</code> and <code>run.subtreeUsage</code>. The migration rewrites stored hand-off parents to role <code>handoff</code></td></tr><tr><td>Wait point</td><td><code>run.waiting</code> (<code>WaitPoint</code>) was always an approval</td><td>A union on <code>kind</code>: <code>ApprovalWaitPoint</code> (<code>kind: &#39;approval&#39;</code>, plus the generic <code>id</code>, equal to <code>approvalId</code>) or <code>DispatchWaitPoint</code> (<code>kind: &#39;dispatch&#39;</code>, <code>runIds</code>). Narrow on <code>kind === &#39;approval&#39;</code> before reading <code>title</code>, <code>approvalId</code> or <code>options</code></td></tr><tr><td>MCP <code>run_&lt;agent&gt;</code> result</td><td><code>waiting: { toolName, title, ... }</code></td><td><code>waiting.kind</code> <code>&#39;approval&#39;</code> (with <code>runId</code> and <code>agent</code>: the run to answer, possibly a descendant) or <code>&#39;dispatch&#39;</code> (<code>get_run</code> only)</td></tr><tr><td>Custom repositories</td><td></td><td><code>Run.parentRunId</code> (set by <code>insert</code> from <code>trigger.parent.runId</code>, a missing parent throws <code>RunNotFoundError</code>), <code>Run.subtreeUsage</code>, <code>RunFindOptions.ids</code>, <code>parentRunId</code>, <code>parentRunIds</code>, <code>hasParent</code> and <code>waitKind</code>, <code>RunUpdateOptions.expectWaitId</code> and <code>keepUpdatedAt</code>, both wait point kinds read back through <code>normalizeWaitPoint()</code>. <code>describeRepositoryContract()</code> checks each (<a href="/repositories/writing-a-repository#lineage-and-wait-points">Lineage and wait points</a>)</td></tr></tbody></table><p>Drain hand-off trees before upgrading: a parent that replays a <code>startHandoff()</code> call under the new effect keys can start a second child, and a stored child of subscription id <code>handoff</code> matches no role unless the agent declares <code>agent.on({ role: &#39;handoff&#39; })</code>.</p><h3 id="database-migration" tabindex="-1">Database migration <a class="header-anchor" href="#database-migration" aria-label="Permalink to &quot;Database migration&quot;">​</a></h3><p>0.6 ships <code>1792800000000-run-lineage.ts</code> (<code>RunLineage1792800000000</code>): <code>chamvi_runs.parent_run_id</code> (indexed, a self foreign key, <code>NOT VALID</code> so legacy children of a deleted parent stay) and <code>subtree_usage</code>, the <code>parent_run_id</code> backfill from <code>trigger.parent.runId</code>, the hand-off parent rewrite, and the generic <code>id</code> on every pending approval wait point, so an approval that waits across the upgrade can still be answered. See <a href="/repositories/database#migrations">Migrations</a>.</p><h2 id="upgrading-to-0-5" tabindex="-1">Upgrading to 0.5 <a class="header-anchor" href="#upgrading-to-0-5" aria-label="Permalink to &quot;Upgrading to 0.5&quot;">​</a></h2><h3 id="breaking-changes-5" tabindex="-1">Breaking changes <a class="header-anchor" href="#breaking-changes-5" aria-label="Permalink to &quot;Breaking changes&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Change</th><th>Before (0.4)</th><th>Replacement (0.5)</th></tr></thead><tbody><tr><td>Node</td><td><code>&gt;=24.3.0</code></td><td><code>&gt;=26.0.0</code></td></tr><tr><td>Base image</td><td><code>ghcr.io/chamvi/node:24</code></td><td><code>ghcr.io/chamvi/node:26</code>; build stages move to <code>node:26-trixie-slim</code>. The <code>24</code> tag stops receiving rebuilds</td></tr><tr><td><code>chamvi build</code> target</td><td><code>node24</code></td><td><code>node26</code></td></tr><tr><td>Sandbox image <code>ghcr.io/chamvi/sandbox-node:24</code></td><td>Rebuilt as a deprecated workspace image</td><td>Not built anymore; use the default <code>ghcr.io/chamvi/sandbox-dev</code> (<code>mise use -g node@26</code>) or your own image</td></tr></tbody></table><h2 id="upgrading-to-0-4" tabindex="-1">Upgrading to 0.4 <a class="header-anchor" href="#upgrading-to-0-4" aria-label="Permalink to &quot;Upgrading to 0.4&quot;">​</a></h2><h3 id="breaking-changes-6" tabindex="-1">Breaking changes <a class="header-anchor" href="#breaking-changes-6" aria-label="Permalink to &quot;Breaking changes&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Change</th><th>Before (0.3)</th><th>Replacement (0.4)</th></tr></thead><tbody><tr><td>Store package renamed</td><td><code>@chamvi/store-typeorm</code></td><td><code>@chamvi/store-db</code>; replace the dependency and every import. Tables and migration history keep their names</td></tr><tr><td>Store aggregate</td><td><code>new MemoryStore(options)</code>, <code>new TypeormStore(options)</code>, facade methods such as <code>engine.store.getRun(id)</code></td><td><code>createMemoryStore(options)</code>, <code>createDatabaseStore(options)</code>, role methods such as <code>engine.store.runs.findOne(id)</code>; every method is mapped on <a href="/repositories/#updating-existing-callers">Stores and repositories</a></td></tr><tr><td>Repository interfaces</td><td><code>IRunStore</code>, <code>IStepStore</code>, <code>ICheckpointStore</code>, <code>IIdempotencyStore</code>, <code>ILockStore</code>, <code>IEffectStore</code>, <code>IStateStore</code>, <code>IArtifactStore</code>, <code>IAgentRevisionStore</code>; <code>IStore</code> extended them</td><td><code>IRunRepository</code>, <code>IStepRepository</code>, <code>ICheckpointRepository</code>, <code>IIdempotencyRepository</code>, <code>ILockRepository</code>, <code>IEffectRepository</code>, <code>IStateRepository</code>, <code>IArtifactRepository</code>, <code>IAgentRevisionRepository</code>; <code>IStore</code> holds one of each (<code>store.runs</code>, <code>store.steps</code>, ...)</td></tr><tr><td>Database store options</td><td><code>TypeormStoreOptions</code></td><td><code>DatabaseStoreOptions</code>; <code>createDatabaseStore()</code> returns <code>DatabaseStore</code></td></tr><tr><td>Purging expired rows</td><td><code>store.purgeExpired(now?)</code> resolving <code>PurgeResult</code></td><td><code>store.idempotency.purgeExpired(now?)</code> and <code>store.locks.purgeExpired(now?)</code>, each resolving the number of deleted rows (<code>@chamvi/app</code> schedules both)</td></tr><tr><td>Agent instructions</td><td><code>AgentDefinition.instructions: string</code></td><td><code>instructions: AgentInstructions</code> (a string or an array of system, user and assistant messages). A string still works; code that reads <code>agent.definition.instructions</code> as a string must handle the array form</td></tr><tr><td>Channel context</td><td><code>ChannelContext.engine: Engine</code>; no conversation intake</td><td><code>ChannelContext.engine: IEngine</code> (type against the interface, not the class); <code>ChannelContext.dispatchConversation(envelope, target)</code> is required: a hand-built context needs one, get both from <code>engine.channelContext(channel)</code></td></tr><tr><td>Engine typing in apps</td><td><code>AppTokens.ENGINE: Engine</code>, <code>ILifecycleHook.engineCreated(engine: Engine)</code></td><td>Both typed <code>IEngine</code>. Cast to <code>Engine</code> only where you need a member outside <code>IEngine</code></td></tr><tr><td><code>Engine.stop()</code></td><td>Stopped polling and the channels</td><td>Also halts the queue and waits for an in-flight <code>start()</code> and <code>prepare()</code> (skill preparation). A skill provider that ignores cancellation holds <code>stop()</code> until it settles</td></tr><tr><td>Cron schedule lock</td><td><code>createStoreScheduleLock(store, owner)</code></td><td><code>createRepositoryScheduleLock(store.locks, owner)</code> (<code>@chamvi/channel-cron</code>, takes an <code>ILockRepository</code>)</td></tr><tr><td>Engine concurrency option</td><td><code>new Engine({ maxConcurrentRuns })</code></td><td><code>new Engine({ concurrencyMaxRuns })</code>; the variable <code>CHAMVI_MAX_CONCURRENT_RUNS</code> is unchanged</td></tr><tr><td>App config concurrency</td><td><code>readConfig(env).engine.maxConcurrentRuns</code></td><td><code>readConfig(env).engine.concurrencyMaxRuns</code> (<code>AppConfig</code>); the variable <code>CHAMVI_MAX_CONCURRENT_RUNS</code> is unchanged</td></tr><tr><td>Run references (memory, database and custom stores)</td><td><code>steps.insert</code>, <code>checkpoints.save</code> and <code>conversations.beginTurn</code> accepted any run id on the memory store; Postgres failed with a raw foreign key error</td><td>All three throw <code>RunNotFoundError</code> for a run the store does not hold and write nothing, on memory and Postgres alike. <code>describeRepositoryContract()</code> checks it, so a custom store must implement it to pass (<a href="/repositories/writing-a-repository#run-references">Run references</a>). Insert the run first; a test that spreads <code>{ ...createMemoryStore(), runs: custom }</code> builds <code>steps</code>/<code>checkpoints</code>/<code>conversations</code> with <code>hasRun</code> over <code>custom</code> (see <a href="/repositories/memory">Memory repositories</a>)</td></tr><tr><td>Node</td><td><code>&gt;=22</code></td><td><code>&gt;=24.3.0</code></td></tr><tr><td>Git credential mode (<code>@chamvi/sandbox</code>)</td><td><code>credentialMode</code> (<code>CredentialMode</code>) and <code>CHAMVI_GIT_CREDENTIAL_MODE</code> chose tools-only or workspace-installed credentials</td><td>Removed; a set variable or option is refused with <code>InvalidAgentDefinitionError</code> naming them: unset the variable and drop the option. Workspace-installed credentials are the only mode; <code>PushPolicy</code> binds <code>git_push</code> only, so restrict writes through token scope and branch protection</td></tr><tr><td>Image requirements (<code>@chamvi/sandbox</code>)</td><td><code>IMAGE_REQUIREMENTS</code> <code>[&#39;sh&#39;, &#39;git&#39;, &#39;timeout&#39;]</code></td><td><code>[&#39;sh&#39;, &#39;git&#39;, &#39;timeout&#39;, &#39;head&#39;, &#39;base64&#39;, &#39;tr&#39;]</code>: the image probe also refuses an image without <code>/bin/sh</code> or without <code>head</code>, <code>base64</code> and <code>tr</code> in <code>/usr/bin</code> or <code>/bin</code> (coreutils or busybox provide them; <code>ghcr.io/chamvi/sandbox-dev</code> has them)</td></tr><tr><td><code>write_file</code> over a file holding an issued token</td><td>Wrote a literal <code>[redacted]</code> over the token</td><td>Each <code>[redacted]</code> the model read is restored in order; content whose markers do not line up, or with <code>[redacted]</code> over an existing file that cannot be read as text, is refused (<code>ValidationError</code>) and nothing is written</td></tr><tr><td>Event-started runs (<code>github</code>, <code>webhook</code>)</td><td>A delivery started a run whose write tools ran at once, so an event-driven auto-merge or auto-reply flow acted without a human</td><td>The <code>github</code> and <code>webhook</code> channels are untrusted ingress: their runs are tainted from the first step, and <code>github_merge_pull_request</code>, <code>github_create_pull_request</code>, <code>github_create_issue</code>, <code>github_propose_change</code>, <code>git_push</code> and a <code>github_create_comment</code> on another issue than the source one wait for an approval (the source issue gets a generic &quot;An outbound operation requires review&quot; comment, never the arguments). Answer it in the approval inbox or through <code>POST /runs/:id/approve</code> (MCP <code>approve_run</code>). An agent whose own policy already decides opts out per tool: <code>trust: { tools: { github_merge_pull_request: { guardWhenTainted: false } } }</code> (<a href="/deployment/github-app#approvals-in-event-started-runs">Approvals in event-started runs</a>)</td></tr><tr><td>Run taint</td><td>No taint column</td><td>Database migration <code>ConversationsRunTaint1792713600000</code> adds <code>chamvi_runs.taint</code> and backfills unfinished runs; it needs downtime (below). Custom stores must persist <code>Run.taint</code> (<a href="/repositories/writing-a-repository#persist-run-taint">Persist run taint</a>)</td></tr></tbody></table><h3 id="new-in-0-4" tabindex="-1">New in 0.4 <a class="header-anchor" href="#new-in-0-4" aria-label="Permalink to &quot;New in 0.4&quot;">​</a></h3><p>Run taint, the outbound gates and repository guidance are new, so 0.3 apps have nothing to migrate beyond the rows above. In their final 0.4 form:</p><ul><li>The coding read and shell tools (<code>read_file</code>, <code>grep</code>, <code>glob</code>, <code>list_files</code>, <code>git_diff</code>, <code>bash</code>, <code>bash_output</code>) taint the run in every workspace, repo-less ones included; opt a tool out with <code>trust.tools: { bash: { taint: false } }</code> only where its output is trusted.</li><li><code>git_push</code> with <code>push: { mode: &#39;approve&#39; }</code> asks once in a tainted run: the outbound gate&#39;s private approval carries the push title and commit log (<code>ToolTrust.approvalDetail</code>, <code>outboundApproved(ctx)</code>) and is answered in the approval inbox or API; <code>push.channel</code> is not asked then. A push the policy refuses is denied before the gate asks.</li><li>A failing repository guidance collection gives <code>instructions: null</code> plus <code>instructionsError</code> in <code>create_workspace</code> and <code>read_file</code>; <code>read_file</code> in a repo-less workspace omits <code>instructions</code>.</li><li><code>ghcr.io/chamvi/sandbox-dev</code> ships the GitHub CLI (<code>gh</code>, the current release at build time); pin the image digest for a fixed version.</li></ul><p>Conversation memory is opt-in and new, so 0.3 apps have nothing to migrate: storage is the engine&#39;s <code>conversationService</code> (both built-in stores carry a conversation repository), policy is <code>createApp({ conversations: { authorize } })</code> or <code>EngineOptions.conversations</code>. See <a href="/guide/conversations">Conversations</a> for the setup.</p><h3 id="database-migration-1" tabindex="-1">Database migration <a class="header-anchor" href="#database-migration-1" aria-label="Permalink to &quot;Database migration&quot;">​</a></h3><p>0.4 ships one new migration, <code>1792713600000-conversations-run-taint.ts</code> (<code>ConversationsRunTaint1792713600000</code>): the conversation tables, the run and checkpoint conversation bindings, the foreign keys (the two on legacy steps and checkpoints <code>NOT VALID</code>, see <a href="/repositories/database#validating-the-legacy-constraints">Validating the legacy constraints</a>), indexes on the new foreign key columns, <code>chamvi_runs.taint</code> and the backfill that taints every <code>queued</code>, <code>running</code>, <code>waiting</code> and <code>interrupted</code> run with <code>{ at: &lt;migration time&gt;, source: &#39;migration:legacy-run&#39; }</code>.</p><div class="warning custom-block"><p class="custom-block-title">Development databases</p><p>A database that ran a pre-release build of this branch recorded <code>Conversations1792713600000</code> (and maybe <code>RunTaint1792800000000</code>). Migrating it fails with &quot;relation already exists&quot;. Recreate the disposable database; never reset a production one for this.</p></div><h3 id="upgrade-procedure-downtime" tabindex="-1">Upgrade procedure (downtime) <a class="header-anchor" href="#upgrade-procedure-downtime" aria-label="Permalink to &quot;Upgrade procedure (downtime)&quot;">​</a></h3><p>Old and new runtimes must never share the store, not even during a rolling update. An old approval poller can post a tainted run&#39;s private approval body to its source channel, and an old worker or job can create or checkpoint untainted runs after the one-time backfill. Claims and locks do not prevent this.</p><ol><li><strong>Suspend the run-job CronJobs</strong> (<code>kubectl patch cronjob &lt;name&gt; -p &#39;{&quot;spec&quot;:{&quot;suspend&quot;:true}}&#39;</code>, or <code>suspend: true</code> on each <code>cronJobs[]</code> entry of the <code>agent-app</code> chart) and wait for running job pods to finish. A <code>Recreate</code> Deployment does not cover CronJobs, and <code>CHAMVI_MIGRATE</code> defaults to <code>true</code> in job mode too: a 0.3 job pod started during the upgrade writes runs the backfill never sees.</li><li><strong>Stop every old process</strong>: scale the Deployment to 0 (ingress, workers, approval pollers) and wait for the pods to exit. Draining executions alone is not enough.</li><li><strong>Migrate in a maintenance window</strong>: run <code>chamvi migrate</code> once with the new image (<code>DATABASE_URL</code> set). Alternatively start the new Deployment with the default <code>CHAMVI_MIGRATE=true</code>; with <code>CHAMVI_MIGRATE=false</code> everywhere, <code>chamvi start --check</code> refuses the unmigrated database.</li><li><strong>Start only 0.4 binaries</strong>: scale the Deployment up, then resume the CronJobs with the new image. Resumed legacy runs are tainted, so their guarded tools ask for approval.</li></ol><p>See <a href="/deployment/replicas#upgrading-to-untrusted-content-gates">Multiple replicas</a> for why each step matters.</p><h3 id="release-time-owner-actions" tabindex="-1">Release-time owner actions <a class="header-anchor" href="#release-time-owner-actions" aria-label="Permalink to &quot;Release-time owner actions&quot;">​</a></h3><p>These are not code changes; the maintainer does them when 0.4.0 is published:</p><ul><li>After the first <code>@chamvi/store-db</code> publish: <code>npm deprecate @chamvi/store-typeorm &quot;renamed to @chamvi/store-db&quot;</code>.</li><li>Check that the <code>NPM_TOKEN</code> used by <code>release.yml</code> (monoship) may create new packages: <code>@chamvi/skills</code> and <code>@chamvi/store-db</code> publish for the first time.</li><li><code>@chamvi/skills</code> depends on a Git URL (<code>git+https://github.com/tada5hi/skills-cli.git#&lt;sha&gt;</code>): registry-only proxies and the agent-template lockfile check refuse it. Publish or vendor the fork before relying on it (<a href="https://github.com/chamvi/chamvi/issues/97" target="_blank" rel="noreferrer">#97</a>).</li><li>Downstream: bump <a href="https://github.com/chamvi/helm" target="_blank" rel="noreferrer">chamvi/helm</a> and <a href="https://github.com/chamvi/agent-template" target="_blank" rel="noreferrer">chamvi/agent-template</a> from <code>^0.3.x</code> to <code>^0.4.0</code> after publishing (Node 24, the CronJob suspend note in the chart README, no <code>CHAMVI_GIT_CREDENTIAL_MODE</code>).</li></ul>',85)])])}const g=o(a,[["render",n]]);export{u as __pageData,g as default};
